// PS5MG's web interface: a thin layer over the job queue in /data/PS5MG/jobs (the worker in mg_main.cpp runs the
// jobs). The image goes to in/<id>.png, the job file gets the trellis-cli arguments, the result is out/<id>.glb.
#include <dirent.h>
#include <sys/stat.h>
#include <unistd.h>

#include <algorithm>
#include <atomic>
#include <cstdio>
#include <cstdlib>
#include <ctime>
#include <fstream>
#include <set>
#include <sstream>

#include "httplib.h"
#include "mg_state.hpp"

#include "mg_index_html.h"  // generated by scripts/build-mg.sh: mg_index_html[], mg_index_html_len

namespace {

std::string esc(const std::string & s) {
    std::string o;
    for (char c : s) {
        switch (c) {
            case '"': o += "\\\""; break;
            case '\\': o += "\\\\"; break;
            case '\n': o += "\\n"; break;
            case '\r': break;
            case '\t': o += ' '; break;
            default:
                if (static_cast<unsigned char>(c) >= 0x20) o += c;
        }
    }
    return o;
}

bool exists(const std::string & p) {
    struct stat st;
    return stat(p.c_str(), &st) == 0;
}

long fsize(const std::string & p) {
    struct stat st;
    return stat(p.c_str(), &st) == 0 ? static_cast<long>(st.st_size) : -1;
}

std::string slurp(const std::string & p) {
    std::ifstream f(p, std::ios::binary);
    std::stringstream ss;
    ss << f.rdbuf();
    return ss.str();
}

std::vector<std::string> list_dir(const std::string & d) {
    std::vector<std::string> v;
    if (DIR * h = opendir(d.c_str())) {
        while (dirent * e = readdir(h)) {
            if (e->d_name[0] != '.') v.push_back(e->d_name);
        }
        closedir(h);
    }
    std::sort(v.begin(), v.end());
    return v;
}

bool ends_with(const std::string & s, const std::string & x) {
    return s.size() >= x.size() && s.compare(s.size() - x.size(), x.size(), x) == 0;
}

// Only [A-Za-z0-9_-]: ids are file names.
bool safe_id(const std::string & id) {
    if (id.empty() || id.size() > 80) return false;
    for (char c : id) {
        if (!isalnum(static_cast<unsigned char>(c)) && c != '_' && c != '-') return false;
    }
    return true;
}

std::string status_of(const std::string & id) {
    const std::string b = std::string(kMgJobs) + "/" + id;
    if (exists(b + ".job")) return "queued";
    if (exists(b + ".running")) return "running";
    if (exists(b + ".done")) return "done";
    if (exists(b + ".failed")) return "failed";
    if (exists(b + ".cancelled")) return "cancelled";
    return "none";
}

std::string field(const httplib::Request & req, const char * name, const std::string & def) {
    return req.has_file(name) ? req.get_file_value(name).content : def;
}

// Weight folders: each folder of /data/PS5MG/models with the TRELLIS.2 set; pixal3d when its flows are there too.
std::string models_json() {
    std::string o = "[";
    for (const auto & d : list_dir(std::string(kMgDir) + "/models")) {
        const std::string p = std::string(kMgDir) + "/models/" + d;
        if (!exists(p + "/ss_flow.gguf")) continue;
        if (o.size() > 1) o += ",";
        o += "{\"dir\":\"" + esc(d) + "\",\"pixal3d\":" + (exists(p + "/pixal3d_ss_flow.gguf") ? "true" : "false") +
             ",\"res1024\":" + (exists(p + "/shape_flow_1024.gguf") ? "true" : "false") + "}";
    }
    return o + "]";
}

std::string job_json(const std::string & id) {
    const std::string st = status_of(id);
    std::string       o  = "{\"id\":\"" + esc(id) + "\",\"status\":\"" + st + "\"";
    const std::string meta = slurp(std::string(kMgJobs) + "/" + id + ".meta");
    if (!meta.empty()) o += ",\"meta\":" + meta;
    const std::string res = slurp(std::string(kMgJobs) + "/" + id + ".result");
    if (!res.empty()) {
        int    rc   = 0;
        double secs = 0;
        std::sscanf(res.c_str(), "%d %lf", &rc, &secs);
        o += ",\"secs\":" + std::to_string(secs);
    }
    const long glb = fsize(std::string(kMgOut) + "/" + id + ".glb");
    if (glb > 0) o += ",\"glb_bytes\":" + std::to_string(glb);
    if (exists(std::string(kMgIn) + "/" + id + ".png")) o += ",\"image\":true";
    return o + "}";
}

std::string jobs_json() {
    std::set<std::string> ids;
    for (const auto & f : list_dir(kMgJobs)) {
        for (const char * ext : {".job", ".running", ".done", ".failed", ".cancelled"}) {
            if (ends_with(f, ext)) ids.insert(f.substr(0, f.size() - std::string(ext).size()));
        }
    }
    std::string o = "[";
    for (auto it = ids.rbegin(); it != ids.rend(); ++it) {  // newest first
        if (o.size() > 1) o += ",";
        o += job_json(*it);
    }
    return o + "]";
}

std::string status_json() {
    std::lock_guard<std::mutex> lk(g_mg.mu);
    std::string o = "{\"busy\":" + std::string(g_mg.job.empty() ? "false" : "true");
    o += ",\"job\":\"" + esc(g_mg.job) + "\",\"stage\":\"" + esc(g_mg.stage) + "\",\"progress\":\"" + esc(g_mg.progress) + "\"";
    o += ",\"elapsed\":" + std::to_string(g_mg.job.empty() ? 0.0 : mg_now() - g_mg.job_t0);
    o += ",\"pool_free_gib\":" + std::to_string(g_mg.pool_free_gib) + ",\"pool_gib\":" + std::to_string(g_mg.pool_gib);
    o += ",\"threads\":" + std::to_string(g_mg.threads) + ",\"tail\":[";
    const size_t from = g_mg.tail.size() > 25 ? g_mg.tail.size() - 25 : 0;
    for (size_t i = from; i < g_mg.tail.size(); i++) o += (i > from ? ",\"" : "\"") + esc(g_mg.tail[i]) + "\"";
    return o + "]}";
}

void send_file(httplib::Response & res, const std::string & path, const char * type, const char * name = nullptr) {
    if (!exists(path)) {
        res.status = 404;
        res.set_content("{\"error\":\"not found\"}", "application/json");
        return;
    }
    // Streamed from disk: a GLB can be tens of MB, and the title has little memory to spare.
    auto size = static_cast<size_t>(fsize(path));
    if (name) res.set_header("Content-Disposition", std::string("attachment; filename=\"") + name + "\"");
    res.set_content_provider(size, type, [path](size_t offset, size_t length, httplib::DataSink & sink) {
        std::ifstream f(path, std::ios::binary);
        f.seekg(static_cast<std::streamoff>(offset));
        std::vector<char> buf(length);
        f.read(buf.data(), static_cast<std::streamsize>(length));
        sink.write(buf.data(), static_cast<size_t>(f.gcount()));
        return true;
    });
}

int clamp_int(const std::string & s, int lo, int hi, int def) {
    if (s.empty()) return def;
    return std::max(lo, std::min(hi, atoi(s.c_str())));
}

}  // namespace

void mg_web_run(int port) {
    mkdir(kMgIn, 0777);
    mkdir(kMgOut, 0777);
    mkdir(kMgJobs, 0777);
    httplib::Server svr;
    svr.set_payload_max_length(64u << 20);
    svr.set_post_routing_handler([](const httplib::Request &, httplib::Response & res) {
        res.set_header("Access-Control-Allow-Origin", "*");
        res.set_header("Cache-Control", "no-store");
    });
    svr.Get("/", [](const httplib::Request &, httplib::Response & res) {
        res.set_content(reinterpret_cast<const char *>(mg_index_html), mg_index_html_len, "text/html; charset=utf-8");
    });
    svr.Get("/api/status", [](const httplib::Request &, httplib::Response & res) {
        res.set_content(status_json(), "application/json");
    });
    svr.Get("/api/models", [](const httplib::Request &, httplib::Response & res) {
        res.set_content(models_json(), "application/json");
    });
    svr.Get("/api/jobs", [](const httplib::Request &, httplib::Response & res) {
        res.set_content(jobs_json(), "application/json");
    });
    svr.Get(R"(/api/jobs/([A-Za-z0-9_-]+)/glb)", [](const httplib::Request & req, httplib::Response & res) {
        send_file(res, std::string(kMgOut) + "/" + req.matches[1].str() + ".glb", "model/gltf-binary",
                  (req.matches[1].str() + ".glb").c_str());
    });
    svr.Get(R"(/api/jobs/([A-Za-z0-9_-]+)/image)", [](const httplib::Request & req, httplib::Response & res) {
        send_file(res, std::string(kMgIn) + "/" + req.matches[1].str() + ".png", "image/png");
    });
    svr.Post(R"(/api/jobs/([A-Za-z0-9_-]+)/cancel)", [](const httplib::Request & req, httplib::Response & res) {
        const std::string b = std::string(kMgJobs) + "/" + req.matches[1].str();
        // Only a job that has not started: a running one is never killed.
        if (exists(b + ".job") && rename((b + ".job").c_str(), (b + ".cancelled").c_str()) == 0) {
            res.set_content("{\"ok\":true}", "application/json");
        } else {
            res.status = 409;
            res.set_content("{\"error\":\"only a queued job can be cancelled\"}", "application/json");
        }
    });
    svr.Post("/api/jobs", [](const httplib::Request & req, httplib::Response & res) {
        auto fail = [&](int code, const std::string & msg) {
            res.status = code;
            res.set_content("{\"error\":\"" + esc(msg) + "\"}", "application/json");
        };
        if (!req.has_file("image") || req.get_file_value("image").content.empty()) return fail(400, "no image");
        const std::string weights = field(req, "weights", "q4");
        const std::string family  = field(req, "family", "trellis");
        if (!safe_id(weights)) return fail(400, "bad weights folder");
        if (family != "trellis" && family != "pixal3d") return fail(400, "family is trellis or pixal3d");
        const std::string wdir = std::string(kMgDir) + "/models/" + weights;
        if (!exists(wdir + "/ss_flow.gguf")) return fail(400, "no weights in " + weights);
        const int         res_px  = field(req, "res", "512") == "1024" ? 1024 : 512;
        const int         seed    = clamp_int(field(req, "seed", ""), 0, 2147483647, 42);
        const int         steps   = clamp_int(field(req, "steps", ""), 1, 50, 8);
        const bool        texture = field(req, "texture", "on") != "off";
        const bool        xatlas  = field(req, "uv", "box") == "xatlas";
        const int         faces   = clamp_int(field(req, "faces", ""), 0, 2000000, 0);
        const std::string fov     = field(req, "fov", "");
        if (family == "pixal3d" && !exists(wdir + "/pixal3d_ss_flow.gguf")) return fail(400, "no Pixal3D weights in " + weights);
        if (res_px == 1024 && !exists(wdir + "/shape_flow_1024.gguf")) return fail(400, "no 1024 weights in " + weights);

        static std::atomic<int> counter{0};
        char                    stamp[32];
        const time_t            now = time(nullptr);
        std::strftime(stamp, sizeof stamp, "%Y%m%d-%H%M%S", std::localtime(&now));
        const std::string id  = std::string("w") + stamp + "-" + std::to_string(counter++);
        const std::string img = std::string(kMgIn) + "/" + id + ".png";
        {
            std::ofstream f(img, std::ios::binary);
            const auto &  c = req.get_file_value("image").content;
            f.write(c.data(), static_cast<std::streamsize>(c.size()));
            if (!f) return fail(500, "cannot store the image");
        }
        std::ostringstream a;
        a << img << ' ' << kMgOut << '/' << id << ".glb -m " << wdir << " --res " << res_px << " -s " << seed << " --steps "
          << steps << " --fa-fast -v" << (xatlas ? " --xatlas" : " --box-uv") << (texture ? "" : " --no-texture");
        if (family == "pixal3d") a << " --model pixal3d";
        if (family == "pixal3d" && !fov.empty()) a << " --fov " << atof(fov.c_str());
        if (faces >= 1000) a << " --faces " << faces;
        const std::string label = field(req, "label", "");
        const std::string meta  = "{\"label\":\"" + esc(label.substr(0, 80)) + "\",\"weights\":\"" + esc(weights) +
                                 "\",\"family\":\"" + family + "\",\"res\":" + std::to_string(res_px) + ",\"seed\":" +
                                 std::to_string(seed) + ",\"steps\":" + std::to_string(steps) + ",\"texture\":" +
                                 (texture ? "true" : "false") + ",\"uv\":\"" + (xatlas ? "xatlas" : "box") +
                                 "\",\"faces\":" + std::to_string(faces) + "}";
        std::ofstream(std::string(kMgJobs) + "/" + id + ".meta") << meta;
        // The job file last, by rename: the worker takes it the moment it is complete.
        std::ofstream(std::string(kMgJobs) + "/" + id + ".job.tmp") << a.str() << '\n';
        rename((std::string(kMgJobs) + "/" + id + ".job.tmp").c_str(), (std::string(kMgJobs) + "/" + id + ".job").c_str());
        res.set_content("{\"id\":\"" + id + "\"}", "application/json");
    });
    svr.Post("/api/quit", [](const httplib::Request &, httplib::Response & res) {
        std::ofstream(std::string(kMgDir) + "/quit") << "1";
        res.set_content("{\"ok\":true}", "application/json");
    });
    std::printf("ps5mg: web interface on port %d\n", port);
    if (!svr.listen("0.0.0.0", port)) std::printf("ps5mg: the web server could not listen on port %d\n", port);
}
